#include <vector>
#include <unordered_map>
#include <unordered_set>

class Solution {
public:
    std::vector<int> maxMexArray(std::vector<int>& nums) {
        int n = nums.size();
        std::unordered_map<int, int> remCounts;
        for (int x : nums) remCounts[x]++;
        std::vector<int> res;
        int i = 0;
        while (i < n) {
            int mex = 0;
            while (remCounts[mex] > 0) mex++;
            if (mex == 0) {
                while (i < n) { res.push_back(0); i++; }
                break;
            }
            std::unordered_set<int> seen;
            int j = i;
            while (j < n) {
                int val = nums[j];
                remCounts[val]--;
                if (val < mex) {
                    seen.insert(val);
                    if ((int)seen.size() == mex) {
                        j++;
                        break;
                    }
                }
                j++;
            }
            res.push_back(mex);
            i = j;
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] maxMexArray(int[] nums) {
        int n = nums.length;
        Map<Integer, Integer> remCounts = new HashMap<>();
        for (int x : nums) remCounts.put(x, remCounts.getOrDefault(x, 0) + 1);
        List<Integer> res = new ArrayList<>();
        int i = 0;
        while (i < n) {
            int mex = 0;
            while (remCounts.getOrDefault(mex, 0) > 0) mex++;
            if (mex == 0) {
                while (i < n) { res.add(0); i++; }
                break;
            }
            Set<Integer> seen = new HashSet<>();
            int j = i;
            while (j < n) {
                int val = nums[j];
                remCounts.put(val, remCounts.get(val) - 1);
                if (val < mex) {
                    seen.add(val);
                    if (seen.size() == mex) {
                        j++;
                        break;
                    }
                }
                j++;
            }
            res.add(mex);
            i = j;
        }
        int[] ans = new int[res.size()];
        for (int k = 0; k < res.size(); k++) ans[k] = res.get(k);
        return ans;
    }
}

